import copy
import json
import math

from air_quality import health as h


def brute(H, W, t, q, pol, opt, bud, ws, zs):
    G = h.robust_policy_grid_regions(H, W, t, q, pol, opt, bud, ws, zs)
    B, R = len(G["budgets"]), len(G["z"])
    idg = [[0] * R for _ in range(B)]
    for reg in G["regions"]:
        for b, r in reg["cells"]:
            idg[b][r] = reg["id"]

    def cp(v):
        return copy.deepcopy(v)

    def segs(side, k):
        out = []
        n = B if side == "budget" else R
        for c in range(n):
            b, r = (c, k) if side == "budget" else (k, c)
            rid = idg[b][r]
            if out and out[-1][2] == rid:
                out[-1][1] = c
            else:
                out.append([c, c, rid, cp(G["states"][b][r])])
        return out

    def events(pre, post):
        links = []
        for i, s0 in enumerate(pre):
            for j, s1 in enumerate(post):
                if s0[2] == s1[2]:
                    lo, hi = max(s0[0], s1[0]), min(s0[1], s1[1])
                    if lo <= hi:
                        links.append((i, j, list(range(lo, hi + 1))))
        # naive DSU over node labels
        parent = {}

        def find(x):
            parent.setdefault(x, x)
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, c):
            parent[find(a)] = find(c)

        for i in range(len(pre)):
            find(("f", i))
        for j in range(len(post)):
            find(("t", j))
        for i, j, _ in links:
            union(("f", i), ("t", j))
        comps = {}
        for node in list(parent):
            comps.setdefault(find(node), []).append(node)
        ev = []
        for root, nodes in comps.items():
            f = sorted(n[1] for n in nodes if n[0] == "f")
            t_ = sorted(n[1] for n in nodes if n[0] == "t")
            ov = set()
            for i, j, cc in links:
                if i in f and j in t_:
                    ov.update(cc)
            if not f:
                k_ = "enter"
            elif not t_:
                k_ = "exit"
            elif len(f) == 1 and len(t_) == 1:
                k_ = "continue"
            elif len(f) == 1:
                k_ = "split"
            elif len(t_) == 1:
                k_ = "merge"
            else:
                k_ = "merge_split"
            ev.append([k_, f, t_, sorted(ov)])
        ev.sort(key=lambda e: (e[1] or [-1], e[2] or [-1]))
        return ev

    def edges(ids):
        e = set()
        for a, c in zip(ids, ids[1:]):
            if a != c:
                e.add((min(a, c), max(a, c)))
        return e

    bsl = [segs("budget", r) for r in range(R)]
    bev = [events(bsl[r], bsl[r + 1]) for r in range(R - 1)]
    bch = []
    for r in range(R - 1):
        f = [idg[b][r] for b in range(B)]
        g = [idg[b][r + 1] for b in range(B)]
        fe, ge = edges(f), edges(g)
        bch.append([
            r, r + 1,
            [[a, c] for a, c in sorted(ge - fe)],
            [[a, c] for a, c in sorted(fe - ge)],
        ])

    zsl = [segs("z", b) for b in range(B)]
    zev = [events(zsl[b], zsl[b + 1]) for b in range(B - 1)]
    zch = []
    for b in range(B - 1):
        f = [idg[b][r] for r in range(R)]
        g = [idg[b + 1][r] for r in range(R)]
        fe, ge = edges(f), edges(g)
        zch.append([
            b, b + 1,
            [[a, c] for a, c in sorted(ge - fe)],
            [[a, c] for a, c in sorted(fe - ge)],
        ])

    return {
        "budgets": list(G["budgets"]),
        "z": list(G["z"]),
        "axes": {
            "budget": {"slices": bsl, "events": bev, "adjacency_changes": bch},
            "z": {"slices": zsl, "events": zev, "adjacency_changes": zch},
        },
    }


def norm(x):
    # canonicalize via json to compare structure; keep numbers as-is
    return json.loads(json.dumps(x))


def check(H, W, t, q, pol, opt, bud, ws, zs, tag):
    got = h.robust_policy_region_flow(H, W, t, q, pol, opt, bud, ws, zs)
    exp = brute(H, W, t, q, pol, opt, bud, ws, zs)
    # key order
    assert list(got) == ["budgets", "z", "axes"], tag
    assert list(got["axes"]) == ["budget", "z"], tag
    for ax in ("budget", "z"):
        assert list(got["axes"][ax]) == ["slices", "events", "adjacency_changes"], tag
    assert norm(got) == norm(exp), tag
    # G copies: budgets/z equal G values
    G = h.robust_policy_grid_regions(H, W, t, q, pol, opt, bud, ws, zs)
    assert got["budgets"] == list(G["budgets"]) and got["z"] == list(G["z"]), tag
    # event kind validity + ascending indices + event length 4
    for ax in ("budget", "z"):
        for pair in got["axes"][ax]["events"]:
            for e in pair:
                assert e[0] in {"enter", "exit", "continue", "split", "merge", "merge_split"}, (tag, e)
                assert e[1] == sorted(e[1]) and e[2] == sorted(e[2])
                assert e[3] == sorted(set(e[3]))
    print(tag, "OK; regions =", len(G["regions"]),
          "budget events =", [len(p) for p in got["axes"]["budget"]["events"]],
          "z events =", [len(p) for p in got["axes"]["z"]["events"]])


