ws = [[1.0, 1.0, 1.0, 1.0], [2.0, 1.0, 1.0, 0.0]]

check(H, W, t, q, pol, opt, [0.0, 1.0, 2.5, 5.0], ws, [0.0, 1.0, 1.96, 3.0], "4x4")
check(H, W, t, q, pol, opt, [0.0, 1.0, 2.5], ws, [1.96], "single z")
check(H, W, t, q, pol, opt, [1.0], ws, [1.0, 1.96], "single budget")
check(H, W, t, q, pol, opt, [1.0], ws, [1.96], "1x1")
check(H, W, t, q, pol, opt, [0.0, 1.0, 2.5, 5.0, 10.0], ws,
      [0.0, 0.5, 1.0, 1.96, 3.0, 4.0], "5x6")

# JSON compatibility incl None
res = h.robust_policy_region_flow(H, W, t, q, pol, opt, [0.0, 2.5], ws, [1.0, 1.96])
s = json.dumps(res)
assert json.loads(s) is not None
print("JSON OK, len =", len(s))

# exception inheritance
for bad, label in [
    ((1.0, 1.0), "dup budgets"),
    ([], "empty zs"),
    ([-1.0], "neg z"),
]:
    try:
        if label == "dup budgets":
            h.robust_policy_region_flow(H, W, t, q, pol, opt, bad, ws, [1.0, 2.0])
        else:
            h.robust_policy_region_flow(H, W, t, q, pol, opt, [1.0], ws, bad)
        raise AssertionError("should have raised: " + label)
    except ValueError:
        print("ValueError OK:", label)

try:
    h.robust_policy_region_flow(H, W, t, q, pol, opt, {1: 2}, ws, [1.0])
    raise AssertionError("type")
